/**
 * Tests for `reEmitButtonsAfterParentSave` — Wave 8 / Builder 8.
 *
 * The helper runs after a parent project view_submission saves successfully.
 * It scans sibling proposals (same intentGroupId) whose pendingProjectName
 * matches the just-saved project's name, marks them resolved (sets
 * resolvedProjectId on each row), then re-emits the bot's button-bearing
 * message via `chat.update` so the previously-disabled task buttons swap
 * action_id from `task_button_disabled` -> `open_create_modal`.
 *
 * Per pre-plan v7 §B2: the button `value` always carries the proposalId from
 * initial render. `chat.update` only updates the action_id (style/emoji are
 * cosmetic). Tests pin this contract explicitly.
 *
 * Failure-mode coverage:
 *   - chat.update returns Slack error -> fall back to chat.postMessage with
 *     same blocks in same channel/thread.
 *   - Parent has no postedMessageTs -> bail gracefully (no throw).
 */
import { describe, it, expect, vi, beforeEach } from "vitest";
import { reEmitButtonsAfterParentSave } from "./multi-detect";

// ----------------------------------------------------------------------------
// Mock proposal shape — mirrors the live botModalProposals row, minus columns
// the helper does not read.
// ----------------------------------------------------------------------------
type MockProposal = {
  id: string;
  toolName: string;
  kind: "create" | "edit";
  intentGroupId: string | null;
  parentProposalId: string | null;
  pendingProjectName: string | null;
  postedMessageTs: string | null;
  postedMessageChannel: string | null;
  resolvedProjectId: string | null;
  status: "pending" | "submitted" | "cancelled" | "expired" | "failed";
  args: string;
};

function makeProposal(p: Partial<MockProposal> & { id: string }): MockProposal {
  return {
    toolName: "create_week_item",
    kind: "create",
    intentGroupId: "ig_test",
    parentProposalId: null,
    pendingProjectName: null,
    postedMessageTs: null,
    postedMessageChannel: null,
    resolvedProjectId: null,
    status: "pending",
    args: JSON.stringify({}),
    ...p,
  };
}

// ----------------------------------------------------------------------------
// Tiny db mock — supports the chained calls the helper makes:
//   - select().from(botModalProposals).where(eq(...)).limit(1)
//     (parent lookup by id)
//   - select().from(botModalProposals).where(eq(intentGroupId, ...))
//     (sibling list)
//   - update(botModalProposals).set({...}).where(eq(id, ...))
//     (resolve siblings)
// ----------------------------------------------------------------------------
function makeDbMock(rows: MockProposal[]) {
  const map = new Map(rows.map((r) => [r.id, r]));
  const updates: Array<{ id?: string; intentGroupId?: string; patch: Partial<MockProposal> }> = [];

  // Match by either id or intentGroupId — whichever the where clause filters by.
  const buildSelectChain = () => {
    let idMatch: string | undefined;
    let intentGroupMatch: string | undefined;
    const exec = (): MockProposal[] => {
      if (idMatch) {
        const r = map.get(idMatch);
        return r ? [r] : [];
      }
      if (intentGroupMatch) {
        return Array.from(map.values()).filter(
          (r) => r.intentGroupId === intentGroupMatch,
        );
      }
      return Array.from(map.values());
    };
    const chain: Record<string, unknown> = {
      from() {
        return chain;
      },
      where(filter: { _idMatch?: string; _intentGroupMatch?: string }) {
        if (filter?._idMatch) idMatch = filter._idMatch;
        if (filter?._intentGroupMatch) intentGroupMatch = filter._intentGroupMatch;
        return chain;
      },
      limit() {
        return Promise.resolve(exec());
      },
      then(resolve: (rows: MockProposal[]) => unknown) {
        return Promise.resolve(exec()).then(resolve);
      },
    };
    return chain;
  };

  const db = {
    select: () => buildSelectChain(),
    update: () => ({
      set: (patch: Partial<MockProposal>) => ({
        where: (filter: { _idMatch?: string; _intentGroupMatch?: string }) => {
          if (filter?._idMatch) {
            updates.push({ id: filter._idMatch, patch });
            const cur = map.get(filter._idMatch);
            if (cur) map.set(filter._idMatch, { ...cur, ...patch });
          }
          return Promise.resolve();
        },
      }),
    }),
  };
  return { db, map, updates };
}

// ----------------------------------------------------------------------------
// Slack client mock — captures chat.update + chat.postMessage calls.
// ----------------------------------------------------------------------------
function makeSlackMock(opts?: { chatUpdateError?: string }) {
  const chatUpdate = vi.fn(async () => {
    if (opts?.chatUpdateError) {
      const err = new Error(opts.chatUpdateError) as Error & {
        data?: { error?: string };
      };
      err.data = { error: opts.chatUpdateError };
      throw err;
    }
    return { ok: true };
  });
  const chatPostMessage = vi.fn().mockResolvedValue({ ok: true, ts: "1714493000.000100" });
  return {
    client: {
      chat: { update: chatUpdate, postMessage: chatPostMessage },
    } as unknown as Parameters<typeof reEmitButtonsAfterParentSave>[2],
    chatUpdate,
    chatPostMessage,
  };
}

// drizzle-orm `eq()` returns a sentinel the db mock can interpret. The helper
// only filters on id and intentGroupId, so we encode both.
beforeEach(() => {
  vi.resetModules();
});

vi.mock("drizzle-orm", async () => {
  const actual = await vi.importActual<Record<string, unknown>>("drizzle-orm");
  return {
    ...actual,
    eq: (col: { name?: string } | unknown, value: unknown) => {
      // The runway-schema column names tell us which filter the helper used.
      const colName =
        typeof col === "object" && col !== null && "name" in (col as Record<string, unknown>)
          ? (col as { name?: string }).name
          : undefined;
      if (colName === "intent_group_id") {
        return { _intentGroupMatch: String(value) };
      }
      return { _idMatch: String(value) };
    },
  };
});

describe("reEmitButtonsAfterParentSave", () => {
  it("resolves a single sibling whose pendingProjectName matches", async () => {
    const parent = makeProposal({
      id: "prop_parent",
      toolName: "create_project",
      intentGroupId: "ig_one",
      postedMessageTs: "1714492800.001000",
      postedMessageChannel: "C_TEST_001",
    });
    const sibling = makeProposal({
      id: "prop_child_match",
      toolName: "create_week_item",
      intentGroupId: "ig_one",
      parentProposalId: "prop_parent",
      pendingProjectName: "AG1 Pro 2026",
    });
    const { db, updates } = makeDbMock([parent, sibling]);
    const { client, chatUpdate, chatPostMessage } = makeSlackMock();

    await reEmitButtonsAfterParentSave(
      "prop_parent",
      "proj_resolved_001",
      "AG1 Pro 2026",
      client,
      db as never,
    );

    // The matching sibling got resolvedProjectId set.
    expect(updates).toContainEqual(
      expect.objectContaining({
        id: "prop_child_match",
        patch: expect.objectContaining({ resolvedProjectId: "proj_resolved_001" }),
      }),
    );
    // chat.update fired exactly once on the parent's posted message.
    expect(chatUpdate).toHaveBeenCalledTimes(1);
    expect(chatPostMessage).not.toHaveBeenCalled();
    const call = chatUpdate.mock.calls[0][0] as {
      channel: string;
      ts: string;
      blocks: Array<Record<string, unknown>>;
    };
    expect(call.channel).toBe("C_TEST_001");
    expect(call.ts).toBe("1714492800.001000");
    expect(Array.isArray(call.blocks)).toBe(true);
  });

  it("with 3 siblings, only the matching one toggles to enabled", async () => {
    const parent = makeProposal({
      id: "prop_parent",
      toolName: "create_project",
      intentGroupId: "ig_three",
      postedMessageTs: "1714492800.001000",
      postedMessageChannel: "C_TEST_001",
    });
    const matching = makeProposal({
      id: "prop_child_match",
      intentGroupId: "ig_three",
      parentProposalId: "prop_parent",
      pendingProjectName: "AG1 Pro 2026",
    });
    // Two siblings whose pendingProjectName does NOT match the just-saved
    // project. They should stay disabled (no resolvedProjectId update) and
    // their action_id must remain task_button_disabled in the re-emitted blocks.
    const sibA = makeProposal({
      id: "prop_child_other_a",
      intentGroupId: "ig_three",
      parentProposalId: "prop_parent",
      pendingProjectName: "Different Project Name",
    });
    const sibB = makeProposal({
      id: "prop_child_other_b",
      intentGroupId: "ig_three",
      parentProposalId: "prop_parent",
      pendingProjectName: "Another Different",
    });
    const { db, updates } = makeDbMock([parent, matching, sibA, sibB]);
    const { client, chatUpdate } = makeSlackMock();

    await reEmitButtonsAfterParentSave(
      "prop_parent",
      "proj_resolved_001",
      "AG1 Pro 2026",
      client,
      db as never,
    );

    const updatedIds = updates.map((u) => u.id);
    expect(updatedIds).toContain("prop_child_match");
    expect(updatedIds).not.toContain("prop_child_other_a");
    expect(updatedIds).not.toContain("prop_child_other_b");

    expect(chatUpdate).toHaveBeenCalledTimes(1);
    const call = chatUpdate.mock.calls[0][0] as {
      blocks: Array<Record<string, unknown>>;
    };
    // Walk the actions block - the matching child gets open_create_modal and
    // siblings retain task_button_disabled. Both populate value=proposalId.
    const actionsBlock = call.blocks.find(
      (b) => (b as { type: string }).type === "actions",
    ) as { elements?: Array<Record<string, unknown>> } | undefined;
    expect(actionsBlock).toBeDefined();
    const els = actionsBlock?.elements ?? [];
    const findByValue = (v: string) =>
      els.find((e) => (e as { value?: string }).value === v) as
        | { action_id?: string; value?: string }
        | undefined;
    const matchedBtn = findByValue("prop_child_match");
    const otherABtn = findByValue("prop_child_other_a");
    const otherBBtn = findByValue("prop_child_other_b");
    expect(matchedBtn?.action_id).toBe("open_create_modal");
    expect(otherABtn?.action_id).toBe("task_button_disabled");
    expect(otherBBtn?.action_id).toBe("task_button_disabled");
  });

  it("when N siblings all match, all toggle to enabled", async () => {
    const parent = makeProposal({
      id: "prop_parent",
      toolName: "create_project",
      intentGroupId: "ig_all",
      postedMessageTs: "1714492800.001000",
      postedMessageChannel: "C_TEST_001",
    });
    const sibs = [1, 2, 3].map((n) =>
      makeProposal({
        id: `prop_child_${n}`,
        intentGroupId: "ig_all",
        parentProposalId: "prop_parent",
        pendingProjectName: "AG1 Pro 2026",
      }),
    );
    const { db, updates } = makeDbMock([parent, ...sibs]);
    const { client, chatUpdate } = makeSlackMock();

    await reEmitButtonsAfterParentSave(
      "prop_parent",
      "proj_resolved_001",
      "AG1 Pro 2026",
      client,
      db as never,
    );

    expect(updates.map((u) => u.id).sort()).toEqual([
      "prop_child_1",
      "prop_child_2",
      "prop_child_3",
    ]);
    expect(chatUpdate).toHaveBeenCalledTimes(1);
  });

  it("falls back to chat.postMessage when chat.update throws cant_update_message", async () => {
    const parent = makeProposal({
      id: "prop_parent",
      toolName: "create_project",
      intentGroupId: "ig_fallback",
      postedMessageTs: "1714492800.001000",
      postedMessageChannel: "C_TEST_001",
    });
    const sibling = makeProposal({
      id: "prop_child",
      intentGroupId: "ig_fallback",
      parentProposalId: "prop_parent",
      pendingProjectName: "AG1 Pro 2026",
    });
    const { db } = makeDbMock([parent, sibling]);
    const { client, chatUpdate, chatPostMessage } = makeSlackMock({
      chatUpdateError: "cant_update_message",
    });

    await reEmitButtonsAfterParentSave(
      "prop_parent",
      "proj_resolved_001",
      "AG1 Pro 2026",
      client,
      db as never,
    );

    expect(chatUpdate).toHaveBeenCalledTimes(1);
    expect(chatPostMessage).toHaveBeenCalledTimes(1);
    const fallback = chatPostMessage.mock.calls[0][0] as {
      channel: string;
      blocks: unknown[];
    };
    expect(fallback.channel).toBe("C_TEST_001");
    expect(Array.isArray(fallback.blocks)).toBe(true);
  });

  it.each(["message_not_found", "edit_window_closed"])(
    "falls back to chat.postMessage on Slack error %s",
    async (slackError) => {
      const parent = makeProposal({
        id: "prop_parent",
        toolName: "create_project",
        intentGroupId: "ig_other_err",
        postedMessageTs: "1714492800.001000",
        postedMessageChannel: "C_TEST_001",
      });
      const sibling = makeProposal({
        id: "prop_child",
        intentGroupId: "ig_other_err",
        parentProposalId: "prop_parent",
        pendingProjectName: "AG1 Pro 2026",
      });
      const { db } = makeDbMock([parent, sibling]);
      const { client, chatPostMessage } = makeSlackMock({
        chatUpdateError: slackError,
      });

      await reEmitButtonsAfterParentSave(
        "prop_parent",
        "proj_resolved_001",
        "AG1 Pro 2026",
        client,
        db as never,
      );

      expect(chatPostMessage).toHaveBeenCalledTimes(1);
    },
  );

  it("does not call chat.postMessage when chat.update succeeds", async () => {
    const parent = makeProposal({
      id: "prop_parent",
      toolName: "create_project",
      intentGroupId: "ig_ok",
      postedMessageTs: "1714492800.001000",
      postedMessageChannel: "C_TEST_001",
    });
    const sibling = makeProposal({
      id: "prop_child",
      intentGroupId: "ig_ok",
      parentProposalId: "prop_parent",
      pendingProjectName: "AG1 Pro 2026",
    });
    const { db } = makeDbMock([parent, sibling]);
    const { client, chatUpdate, chatPostMessage } = makeSlackMock();

    await reEmitButtonsAfterParentSave(
      "prop_parent",
      "proj_resolved_001",
      "AG1 Pro 2026",
      client,
      db as never,
    );

    expect(chatUpdate).toHaveBeenCalledTimes(1);
    expect(chatPostMessage).not.toHaveBeenCalled();
  });

  it("bails gracefully (no throw, no slack calls) when parent has no postedMessageTs", async () => {
    const parent = makeProposal({
      id: "prop_parent",
      toolName: "create_project",
      intentGroupId: "ig_no_msg",
      postedMessageTs: null,
      postedMessageChannel: null,
    });
    const sibling = makeProposal({
      id: "prop_child",
      intentGroupId: "ig_no_msg",
      parentProposalId: "prop_parent",
      pendingProjectName: "AG1 Pro 2026",
    });
    const { db, updates } = makeDbMock([parent, sibling]);
    const { client, chatUpdate, chatPostMessage } = makeSlackMock();

    await expect(
      reEmitButtonsAfterParentSave(
        "prop_parent",
        "proj_resolved_001",
        "AG1 Pro 2026",
        client,
        db as never,
      ),
    ).resolves.not.toThrow();

    // Sibling should still get resolvedProjectId set (DB consistency wins)
    // even when the slack re-emit can't fire.
    expect(updates.find((u) => u.id === "prop_child")).toBeDefined();
    expect(chatUpdate).not.toHaveBeenCalled();
    expect(chatPostMessage).not.toHaveBeenCalled();
  });

  it("bails when parent proposal lookup misses (no throw, no updates, no slack calls)", async () => {
    const { db, updates } = makeDbMock([]);
    const { client, chatUpdate, chatPostMessage } = makeSlackMock();

    await expect(
      reEmitButtonsAfterParentSave(
        "prop_does_not_exist",
        "proj_anything",
        "AG1 Pro 2026",
        client,
        db as never,
      ),
    ).resolves.not.toThrow();

    expect(updates).toHaveLength(0);
    expect(chatUpdate).not.toHaveBeenCalled();
    expect(chatPostMessage).not.toHaveBeenCalled();
  });
});

/**
 * Wave 8 / Builder 8 — multi-detect chat.update helper.
 *
 * After a parent project view_submission saves successfully, the bot's
 * button-bearing reply (a single message that previously rendered a primary
 * "open project modal" button + 1..N disabled "task — save project first"
 * buttons) needs to be re-emitted with task buttons swapped from
 * `task_button_disabled` to `open_create_modal`.
 *
 * Per pre-plan v7 §B2 (locked):
 *   - Buttons ALWAYS populate `value` with the proposalId from initial render.
 *     `chat.update` only flips action_id (and cosmetic styling); the proposalId
 *     never changes mid-flight.
 *   - Only siblings whose `pendingProjectName` matches the just-saved project
 *     name are eligible to enable. Others stay disabled (they belong to a
 *     different parent that hasn't been saved yet).
 *
 * Failure-mode contract:
 *   - chat.update can fail with `message_not_found`, `cant_update_message`, or
 *     `edit_window_closed` (60-second cap on bot-message edits). On any of
 *     these, fall back to `chat.postMessage` so the user still gets the
 *     enabled buttons.
 *   - If the parent proposal has no `postedMessageTs` (e.g. the bot intercept
 *     hadn't posted a button-bearing reply for some reason), bail gracefully:
 *     resolve sibling DB rows but skip slack calls.
 *   - Slack errors that are not edit-window related still throw to the caller.
 */
import { eq } from "drizzle-orm";
import { botModalProposals } from "@/lib/db/runway-schema";
import type { WebClient } from "@slack/web-api";

// ----------------------------------------------------------------------------
// Types
// ----------------------------------------------------------------------------

/**
 * Loose `db` type — we only need the chained operations the helper uses.
 * Caller passes `getRunwayDb()` (or a test mock with the same chain shape).
 */
export interface MultiDetectDb {
  select: () => {
    from: (table: unknown) => {
      where: (filter: unknown) => Promise<Array<Record<string, unknown>>> & {
        limit?: (n: number) => Promise<Array<Record<string, unknown>>>;
      };
    };
  };
  update: (table: unknown) => {
    set: (patch: Record<string, unknown>) => {
      where: (filter: unknown) => Promise<unknown>;
    };
  };
}

interface ProposalRow {
  id: string;
  toolName: string;
  intentGroupId: string | null;
  parentProposalId: string | null;
  pendingProjectName: string | null;
  postedMessageTs: string | null;
  postedMessageChannel: string | null;
  resolvedProjectId: string | null;
  status: string;
  args: string;
}

// Slack API errors we recognize as "post a fresh follow-up instead of editing".
// `cant_update_message` covers most cases; `message_not_found` fires when the
// bot's original post got deleted; `edit_window_closed` is the 60s cap on
// bot-message edits in some channel types.
const FALLBACK_ERRORS = new Set([
  "message_not_found",
  "cant_update_message",
  "edit_window_closed",
]);

function isFallbackError(err: unknown): boolean {
  if (!err || typeof err !== "object") return false;
  const e = err as { data?: { error?: string }; message?: string };
  if (e.data && typeof e.data.error === "string" && FALLBACK_ERRORS.has(e.data.error)) {
    return true;
  }
  if (typeof e.message === "string") {
    for (const code of FALLBACK_ERRORS) {
      if (e.message.includes(code)) return true;
    }
  }
  return false;
}

// ----------------------------------------------------------------------------
// Block-emit helper
// ----------------------------------------------------------------------------

/**
 * Build the actions block for the re-emitted message. Each sibling renders
 * one button. The action_id is `open_create_modal` for siblings now resolved
 * (resolvedProjectId set), `task_button_disabled` for those still pending.
 * The button `value` is always the proposalId, per §B2.
 */
function buildActionsBlock(siblings: ProposalRow[]): Record<string, unknown> {
  const elements = siblings.map((s) => {
    const enabled = !!s.resolvedProjectId;
    const text = labelForSibling(s, enabled);
    const button: Record<string, unknown> = {
      type: "button",
      action_id: enabled ? "open_create_modal" : "task_button_disabled",
      text: { type: "plain_text", text, emoji: true },
      value: s.id,
    };
    if (enabled) button.style = "primary";
    return button;
  });
  return {
    type: "actions",
    block_id: "multi_detect_actions",
    elements,
  };
}

function labelForSibling(s: ProposalRow, enabled: boolean): string {
  // Toolname tells us if it's a project (the parent itself) or a task. The
  // parent button always renders enabled.
  const isProject = s.toolName === "create_project";
  if (isProject) {
    return enabled ? "Project (saved)" : "Project: open form";
  }
  // Tasks: try to derive a name from args.title for nicer copy. Fall back to
  // generic copy if args is missing or unparseable - the proposalId still
  // routes correctly via `value`.
  let title = "Task";
  try {
    const parsed = JSON.parse(s.args ?? "{}") as Record<string, unknown>;
    if (typeof parsed.title === "string" && parsed.title.length > 0) {
      title = `Task: ${parsed.title}`;
    }
  } catch {
    // ignore
  }
  return enabled ? title : `${title} - save project first`;
}

function buildHeaderBlock(savedAny: boolean): Record<string, unknown> {
  const text = savedAny
    ? "Got it - I caught a few items. Project saved - tasks are now enabled."
    : "Got it - I caught a few items. Click each below to review and save.";
  return {
    type: "section",
    block_id: "multi_detect_header",
    text: { type: "mrkdwn", text },
  };
}

// ----------------------------------------------------------------------------
// Public helper
// ----------------------------------------------------------------------------

/**
 * Re-emit the bot's button-bearing message after the parent project save
 * resolves. See module-level comment for the §B2 contract.
 *
 * @param parentProposalId  The proposalId for the project row that just saved.
 * @param resolvedProjectId The new projects.id row id from the save.
 * @param savedProjectName  The project name that was saved - used to match
 *                          siblings whose pendingProjectName equals this.
 * @param slack             A Slack WebClient (or test mock).
 * @param db                The runway db handle (or test mock).
 */
export async function reEmitButtonsAfterParentSave(
  parentProposalId: string,
  resolvedProjectId: string,
  savedProjectName: string,
  slack: WebClient,
  db: MultiDetectDb,
): Promise<void> {
  // 1. Look up the parent proposal.
  const parentRows = (await db
    .select()
    .from(botModalProposals)
    .where(eq(botModalProposals.id, parentProposalId))) as ProposalRow[];
  const parent = parentRows[0];
  if (!parent) return;

  const intentGroupId = parent.intentGroupId;
  if (!intentGroupId) {
    // Single-detect (no group). No siblings to scan; nothing to do here.
    return;
  }

  // 2. Pull all siblings (incl. parent itself) sharing the intent group.
  const siblings = (await db
    .select()
    .from(botModalProposals)
    .where(eq(botModalProposals.intentGroupId, intentGroupId))) as ProposalRow[];

  // 3. Mark eligible siblings resolved. Eligibility: pendingProjectName
  //    matches the just-saved project name (case-insensitive trim) AND the
  //    sibling is still pending (not already submitted/cancelled/expired).
  const target = savedProjectName.trim().toLowerCase();
  const updatedSiblings: ProposalRow[] = [];
  for (const s of siblings) {
    const isEligible =
      s.id !== parentProposalId &&
      s.status === "pending" &&
      !s.resolvedProjectId &&
      typeof s.pendingProjectName === "string" &&
      s.pendingProjectName.trim().toLowerCase() === target;
    if (isEligible) {
      await db
        .update(botModalProposals)
        .set({ resolvedProjectId })
        .where(eq(botModalProposals.id, s.id));
      updatedSiblings.push({ ...s, resolvedProjectId });
    } else {
      updatedSiblings.push(s);
    }
  }

  // 4. Bail gracefully if the parent message location wasn't recorded - we
  //    have no message to update or thread to follow up in.
  if (!parent.postedMessageTs || !parent.postedMessageChannel) return;

  // 5. Build the re-emit blocks. Parent first (matches initial render order),
  //    then siblings sorted by id for stable button order.
  const parentSelf: ProposalRow = {
    ...parent,
    resolvedProjectId: parent.resolvedProjectId ?? resolvedProjectId,
  };
  const taskSiblings = updatedSiblings
    .filter((s) => s.id !== parentProposalId)
    .sort((a, b) => a.id.localeCompare(b.id));
  const orderedForButtons = [parentSelf, ...taskSiblings];

  const blocks = [
    buildHeaderBlock(true),
    buildActionsBlock(orderedForButtons),
  ];
  const text =
    "Got it - I caught a few items. Project saved - tasks are now enabled.";

  // 6. Try chat.update first; fall back to chat.postMessage on edit-window
  //    errors. Re-throw anything else - the caller's Inngest function will
  //    surface the failure to the user via the standard error path.
  try {
    await slack.chat.update({
      channel: parent.postedMessageChannel,
      ts: parent.postedMessageTs,
      text,
      blocks,
    });
  } catch (err) {
    if (!isFallbackError(err)) throw err;
    await slack.chat.postMessage({
      channel: parent.postedMessageChannel,
      thread_ts: parent.postedMessageTs,
      text,
      blocks,
    });
  }
}

/**
 * Slack interactivity webhook handler.
 *
 * POST /api/slack/interactivity
 *
 * Accepts every Slack interactive payload type:
 *   - block_actions      (button clicks, checkbox toggles, picker changes)
 *   - view_submission    (modal "Save" submit)
 *   - view_closed        (modal cancel / dismiss with notify_on_close=true)
 *   - shortcut           (global / message shortcuts - currently unused)
 *
 * Security mirrors `/api/slack/events`:
 *   - HMAC-SHA256 signature verification on every request via
 *     `verifySlackSignature` (5-minute replay window enforced inside).
 *   - Tampered or stale requests -> 401.
 *   - Misconfigured server (no `SLACK_SIGNING_SECRET`) -> 400 per pre-plan v7.
 *
 * Body shape: Slack sends interactive payloads as
 * `application/x-www-form-urlencoded` with a single `payload=<json>` field -
 * NOT plain JSON like the Events API. We parse the URLSearchParams and
 * `JSON.parse` the `payload` value before routing.
 *
 * Routing strategy: dispatch on `payload.type`, then drill in by
 * `actions[0].action_id` (block_actions) or `view.callback_id`
 * (view_submission/view_closed).
 *
 * Wave 8 (Builder 8) wires the live action/callback handlers below; view_closed
 * still throws NotImplementedError until Wave 11.
 */

import { eq } from "drizzle-orm";
import { verifySlackSignature } from "@/lib/slack/verify";
import { getSlackClient } from "@/lib/slack/client";
import { getRunwayDb } from "@/lib/db/runway";
import { botModalProposals } from "@/lib/db/runway-schema";
import { fuzzyMatchCandidates } from "@/lib/runway/fuzzy-match";
import {
  BASELINE_PARENT_PICKER_HINT,
  formatMultiMatchHint,
  PARENT_PROJECT_NOT_FOUND,
  TASK_BUTTON_DISABLED,
} from "@/lib/slack/modals/copy";
import { buildTaskModal } from "@/lib/slack/modals/task";
import {
  buildProjectModal,
  buildEphemeralRetainerToggle,
  type BlockActionsPayload,
} from "@/lib/slack/modals/project";
import { buildTeamMemberModal } from "@/lib/slack/modals/team-member";
import { getProjectsFiltered } from "@/lib/runway/operations-reads-clients";
import { inngest } from "@/lib/inngest/client";

// -----------------------------------------------------------------------------
// Payload types - discriminated union, just enough for type-safe dispatch.
// -----------------------------------------------------------------------------

/** Single action element inside a block_actions payload's `actions` array. */
interface SlackAction {
  action_id?: string;
  block_id?: string;
  type?: string;
  value?: string;
  selected_option?: { value?: string };
  selected_options?: Array<{ value?: string }>;
  // Slack adds many other fields per action type; carry them through opaquely.
  [key: string]: unknown;
}

interface SlackBlockActionsPayload {
  type: "block_actions";
  user?: { id?: string; team_id?: string };
  team?: { id?: string };
  trigger_id?: string;
  response_url?: string | null;
  view?: SlackView;
  channel?: { id?: string } | null;
  channel_id?: string | null;
  actions?: SlackAction[];
  [key: string]: unknown;
}

/** A Slack modal view as it appears inside view_submission/view_closed. */
interface SlackView {
  id?: string;
  hash?: string;
  callback_id?: string;
  private_metadata?: string;
  state?: { values?: Record<string, unknown> };
  [key: string]: unknown;
}

interface SlackViewSubmissionPayload {
  type: "view_submission";
  user?: { id?: string };
  team?: { id?: string };
  trigger_id?: string;
  view?: SlackView;
  [key: string]: unknown;
}

interface SlackViewClosedPayload {
  type: "view_closed";
  user?: { id?: string };
  team?: { id?: string };
  view?: SlackView;
  is_cleared?: boolean;
  [key: string]: unknown;
}

interface SlackShortcutPayload {
  type: "shortcut";
  callback_id?: string;
  user?: { id?: string };
  team?: { id?: string };
  trigger_id?: string;
  [key: string]: unknown;
}

export type SlackInteractionPayload =
  | SlackBlockActionsPayload
  | SlackViewSubmissionPayload
  | SlackViewClosedPayload
  | SlackShortcutPayload;

// -----------------------------------------------------------------------------
// Sentinel error - kept for view_closed (Wave 11 wires it). Tests assert on
// the class so subsequent edits don't break the dispatch contract.
// -----------------------------------------------------------------------------

export class NotImplementedError extends Error {
  constructor(message: string) {
    super(message);
    this.name = "NotImplementedError";
  }
}

// -----------------------------------------------------------------------------
// Schema-truth callback id list. Keeps the inngest event's modalCallbackId
// field strongly typed without re-declaring the union here.
// -----------------------------------------------------------------------------
const VIEW_SUBMISSION_CALLBACKS = [
  "runway_new_task",
  "runway_new_project",
  "runway_new_team_member",
  "runway_edit_task",
  "runway_edit_project",
  "runway_edit_team_member",
] as const;
type ModalCallbackId = (typeof VIEW_SUBMISSION_CALLBACKS)[number];

function isModalCallbackId(v: string | undefined): v is ModalCallbackId {
  return typeof v === "string" && (VIEW_SUBMISSION_CALLBACKS as readonly string[]).includes(v);
}

// -----------------------------------------------------------------------------
// Route handler
// -----------------------------------------------------------------------------

export async function POST(request: Request): Promise<Response> {
  // Read the raw body BEFORE any parsing - HMAC is computed over the exact
  // bytes Slack sent, including URL-encoding.
  const rawBody = await request.text();

  const signingSecret = process.env.SLACK_SIGNING_SECRET;
  const signature = request.headers.get("x-slack-signature");
  const timestamp = request.headers.get("x-slack-request-timestamp");

  if (!signingSecret || !signature || !timestamp) {
    return new Response("Bad Request", { status: 400 });
  }

  if (!verifySlackSignature(signingSecret, signature, timestamp, rawBody)) {
    return new Response("Unauthorized", { status: 401 });
  }

  // URL-decode the form body and pull the single `payload` field.
  const params = new URLSearchParams(rawBody);
  const payloadStr = params.get("payload");
  if (!payloadStr) {
    return new Response("Bad Request", { status: 400 });
  }

  let payload: SlackInteractionPayload;
  try {
    payload = JSON.parse(payloadStr) as SlackInteractionPayload;
  } catch {
    return new Response("Bad Request", { status: 400 });
  }

  switch (payload.type) {
    case "block_actions":
      return await handleBlockActions(payload);
    case "view_submission":
      return await handleViewSubmission(payload);
    case "view_closed":
      return await handleViewClosed(payload);
    case "shortcut":
      return await handleShortcut(payload);
    default:
      return new Response("Bad Request", { status: 400 });
  }
}

// -----------------------------------------------------------------------------
// block_actions dispatch
// -----------------------------------------------------------------------------

async function handleBlockActions(
  payload: SlackBlockActionsPayload,
): Promise<Response> {
  const action = payload.actions?.[0];
  const actionId = action?.action_id;

  switch (actionId) {
    case "open_create_modal":
      return await handleOpenCreateModal(payload, action!);
    case "is_retainer_checkbox":
      return await handleRetainerToggle(payload);
    case "task_button_disabled":
      return await handleTaskButtonDisabled(payload, action!);
    case "target_entity_picker":
      return await handleTargetEntityPicker(payload, action!);
    default:
      // Repeater rows, in-modal pickers without `dispatch_action`, and any
      // action_id we don't explicitly handle on the server are no-ops here:
      // Slack handles the visual state client-side, and we ack with 200 so
      // Slack doesn't show the "didn't work" warning to the user.
      return new Response("OK", { status: 200 });
  }
}

// -----------------------------------------------------------------------------
// open_create_modal - the primary "open the form" button on a bot intercept
// or slash-command stub. Loads the staged proposal, runs caller-side fuzzy
// match for parent-picker hints, then opens the right modal via views.open.
// trigger_id has 3-second validity from Slack: we keep the path tight (one
// DB roundtrip + at most one fuzzy lookup before views.open).
// -----------------------------------------------------------------------------

async function handleOpenCreateModal(
  payload: SlackBlockActionsPayload,
  action: SlackAction,
): Promise<Response> {
  const proposalId = action.value;
  const triggerId = payload.trigger_id;
  const channelId = payload.channel?.id ?? payload.channel_id ?? undefined;

  if (!proposalId || typeof proposalId !== "string") {
    return new Response("OK", { status: 200 });
  }

  const proposal = await loadProposal(proposalId);
  if (!proposal) {
    await tryPostEphemeral(channelId, payload.user?.id, "I couldn't find that draft - it may have expired. Try the slash command again.");
    return new Response("OK", { status: 200 });
  }

  // Validate proposal lifecycle.
  const now = Date.now();
  const expiresAtMs =
    proposal.expiresAt instanceof Date
      ? proposal.expiresAt.getTime()
      : new Date(proposal.expiresAt as unknown as string).getTime();
  if (proposal.status === "submitted") {
    await tryPostEphemeral(channelId, payload.user?.id, "That draft was already submitted.");
    return new Response("OK", { status: 200 });
  }
  if (proposal.status === "cancelled") {
    await tryPostEphemeral(channelId, payload.user?.id, "That draft was cancelled. Start fresh with the slash command.");
    return new Response("OK", { status: 200 });
  }
  if (proposal.status === "expired" || expiresAtMs <= now) {
    await tryPostEphemeral(channelId, payload.user?.id, "That draft expired. Try the slash command again.");
    return new Response("OK", { status: 200 });
  }

  // Parse args.
  let args: Record<string, unknown> = {};
  try {
    args = JSON.parse(proposal.args ?? "{}") as Record<string, unknown>;
  } catch {
    args = {};
  }

  const toolName = proposal.toolName;
  const kind = toolKind(toolName);

  // For Project tool with isRetainer=true, retainerMode wins and BOTH hints
  // are suppressed regardless of caller-side fuzzy match.
  const isRetainerProject =
    kind === "project" && (args.isRetainer === true || args.isRetainer === "true");

  // Caller-side fuzzy match for parent-picker hints. Only fires for create
  // flows that have a parent name AND a parent picker (Task, non-retainer
  // Project). Team Member has no parent picker. Edit flows don't trigger
  // this branch - they use the slash-command lookup, which Builder 3 owns.
  let multiMatchHint: string | undefined;
  let baselineHint: string | undefined;
  if (proposal.kind === "create" && !isRetainerProject) {
    if (kind === "task" || kind === "project") {
      baselineHint = BASELINE_PARENT_PICKER_HINT;
      const parentName =
        kind === "task"
          ? (args.parentProjectName as string | undefined)
          : (args.parentRetainerName as string | undefined);
      const clientSlug = (args.clientSlug as string | undefined) ?? undefined;
      if (typeof parentName === "string" && parentName.trim().length > 0) {
        const candidates = await getProjectsFiltered(
          clientSlug ? { clientSlug } : undefined,
        );
        const matches = fuzzyMatchCandidates(
          parentName,
          (candidates ?? []) as Array<{ name?: string }>,
          (c) => (typeof c.name === "string" ? c.name : ""),
        );
        if (matches.length > 1) {
          const copyKind = kind === "task" ? "project" : "retainer";
          multiMatchHint = formatMultiMatchHint(matches.length, parentName, copyKind);
        }
      }
    }
  }

  // Build the right view for this kind.
  const view = buildViewForOpen({
    kind,
    mode: proposal.kind,
    proposalId: proposal.id,
    args,
    retainerMode: !!isRetainerProject,
    multiMatchHint,
    baselineHint,
    currentValues: proposal.kind === "edit" ? args : undefined,
  });

  if (!view) return new Response("OK", { status: 200 });
  if (!triggerId) return new Response("OK", { status: 200 });

  try {
    await getSlackClient().views.open({ trigger_id: triggerId, view });
  } catch (err) {
    // views.open failure typically means trigger_id expired (>3s) or the modal
    // shape is malformed. Surface a soft-warn ephemeral so the user knows to
    // retry rather than staring at a silent failure.
    console.error("[slack-interactivity] views.open failed", err);
    await tryPostEphemeral(channelId, payload.user?.id, "I couldn't open that form. Try the slash command again.");
  }
  return new Response("OK", { status: 200 });
}

// -----------------------------------------------------------------------------
// is_retainer_checkbox - flip the project modal between project and retainer
// variants while preserving user-typed values. Builder 5 exported the helper.
// -----------------------------------------------------------------------------

async function handleRetainerToggle(
  payload: SlackBlockActionsPayload,
): Promise<Response> {
  const responseAction = buildEphemeralRetainerToggle(payload as BlockActionsPayload);
  return new Response(JSON.stringify(responseAction), {
    status: 200,
    headers: { "Content-Type": "application/json" },
  });
}

// -----------------------------------------------------------------------------
// task_button_disabled - clicked while the parent project hasn't saved yet.
// Surface the locked TASK_BUTTON_DISABLED ephemeral. If the row is already
// resolved, the multi-detect helper should have swapped action_id back to
// open_create_modal - log a warn but don't error.
// -----------------------------------------------------------------------------

async function handleTaskButtonDisabled(
  payload: SlackBlockActionsPayload,
  action: SlackAction,
): Promise<Response> {
  const proposalId = action.value;
  const channelId = payload.channel?.id ?? payload.channel_id ?? undefined;
  if (!proposalId || typeof proposalId !== "string") {
    return new Response("OK", { status: 200 });
  }
  const proposal = await loadProposal(proposalId);
  if (!proposal) {
    return new Response("OK", { status: 200 });
  }
  if (!proposal.resolvedProjectId) {
    await tryPostEphemeral(channelId, payload.user?.id, TASK_BUTTON_DISABLED);
    return new Response("OK", { status: 200 });
  }
  // Defensive branch: chat.update should have re-emitted with action_id =
  // open_create_modal once the parent saved. Reaching this point means the
  // user clicked an old/cached version of the button. Log + ack.
  console.warn(
    "[slack-interactivity] task_button_disabled clicked on resolved proposal",
    { proposalId, resolvedProjectId: proposal.resolvedProjectId },
  );
  // Surface PARENT_PROJECT_NOT_FOUND only if the proposal is genuinely lost;
  // here we just ack since the proposal is resolved.
  void PARENT_PROJECT_NOT_FOUND;
  return new Response("OK", { status: 200 });
}

// -----------------------------------------------------------------------------
// target_entity_picker - edit-flow disambiguation. User picked which entity
// to edit; we update the proposal row's targetEntityId/Type and re-render the
// modal with the picked entity's currentValues populated.
// -----------------------------------------------------------------------------

async function handleTargetEntityPicker(
  payload: SlackBlockActionsPayload,
  action: SlackAction,
): Promise<Response> {
  const view = payload.view;
  if (!view?.id) {
    return new Response("OK", { status: 200 });
  }
  const meta = parsePrivateMetadata(view.private_metadata);
  const proposalId = meta.proposalId;
  if (!proposalId) {
    return new Response("OK", { status: 200 });
  }
  const selected =
    action.selected_option?.value ?? action.selected_options?.[0]?.value ?? undefined;
  if (!selected) {
    return new Response("OK", { status: 200 });
  }

  const proposal = await loadProposal(proposalId);
  if (!proposal) {
    return new Response("OK", { status: 200 });
  }
  const kind = toolKind(proposal.toolName);
  const targetType =
    kind === "task" ? "week_item" : kind === "project" ? "project" : "team_member";

  // Persist the picked target on the proposal row.
  await getRunwayDb()
    .update(botModalProposals)
    .set({
      targetEntityId: selected,
      targetEntityType: targetType,
    })
    .where(eq(botModalProposals.id, proposalId));

  // Re-render the modal with currentValues set. Args may already carry the
  // selected entity in a `candidates` shape - in production the entity row
  // would be fetched fresh; here we pass through whatever's on the proposal
  // plus the selected id so the view builder can echo it.
  let args: Record<string, unknown> = {};
  try {
    args = JSON.parse(proposal.args ?? "{}") as Record<string, unknown>;
  } catch {
    args = {};
  }
  const currentValues = { ...args, id: selected };
  const newView = buildViewForOpen({
    kind,
    mode: "edit",
    proposalId,
    args,
    retainerMode: false,
    currentValues,
    baselineHint: kind === "team-member" ? undefined : BASELINE_PARENT_PICKER_HINT,
  });

  if (newView) {
    try {
      await getSlackClient().views.update({
        view_id: view.id,
        hash: typeof view.hash === "string" ? view.hash : undefined,
        view: newView as Record<string, unknown>,
      } as Parameters<ReturnType<typeof getSlackClient>["views"]["update"]>[0]);
    } catch (err) {
      console.error("[slack-interactivity] views.update failed", err);
    }
  }
  return new Response("OK", { status: 200 });
}

// -----------------------------------------------------------------------------
// view_submission dispatch - acknowledge with HTTP 200 within 3s, dispatch
// inngest event for async write. Builder 10 owns the consumer.
// -----------------------------------------------------------------------------

async function handleViewSubmission(
  payload: SlackViewSubmissionPayload,
): Promise<Response> {
  const callbackId = payload.view?.callback_id;
  if (!callbackId) {
    return new Response("Bad Request", { status: 400 });
  }
  if (!isModalCallbackId(callbackId)) {
    return new Response("Bad Request", { status: 400 });
  }

  const meta = parsePrivateMetadata(payload.view?.private_metadata);
  const proposalId = meta.proposalId;
  if (!proposalId) {
    return new Response("Bad Request", { status: 400 });
  }

  // Resolve channelId/threadTs from the proposal row (the view payload itself
  // doesn't carry channel context for view_submission). Best-effort: if the
  // lookup fails, ship an empty channelId and let Builder 10's consumer
  // surface the ambiguity to the user via the standard error path.
  let channelId = "";
  let threadTs: string | null = null;
  const proposal = await loadProposal(proposalId);
  if (proposal) {
    channelId = proposal.channelId ?? "";
    threadTs = proposal.threadTs ?? null;
  }

  const stateValuesRaw = payload.view?.state?.values;
  const stateValues = isStateValuesShape(stateValuesRaw) ? stateValuesRaw : {};

  await inngest.send({
    name: "slack-modal/submit",
    data: {
      proposalId,
      modalCallbackId: callbackId,
      stateValues,
      userId: payload.user?.id ?? "",
      teamId: payload.team?.id ?? "",
      channelId,
      threadTs,
      triggerId: payload.trigger_id ?? "",
      submittedAt: new Date().toISOString(),
    },
  });

  // Empty body = "submit succeeded, close the modal". Builder 10's consumer
  // takes it from here.
  return new Response(JSON.stringify({}), {
    status: 200,
    headers: { "Content-Type": "application/json" },
  });
}

// -----------------------------------------------------------------------------
// view_closed dispatch - Wave 11 wires this.
// -----------------------------------------------------------------------------

async function handleViewClosed(
  _payload: SlackViewClosedPayload,
): Promise<Response> {
  // Wave 11 - telemetry + draft cleanup when a user dismisses the modal.
  throw new NotImplementedError("view_closed - Wave 11 wires this");
}

// -----------------------------------------------------------------------------
// shortcut dispatch
// -----------------------------------------------------------------------------

async function handleShortcut(
  _payload: SlackShortcutPayload,
): Promise<Response> {
  // No global or message shortcuts wired yet. Ack so Slack doesn't retry.
  return new Response("OK", { status: 200 });
}

// -----------------------------------------------------------------------------
// Helpers
// -----------------------------------------------------------------------------

interface ProposalRow {
  id: string;
  toolName: string;
  kind: "create" | "edit";
  args: string;
  targetEntityId: string | null;
  targetEntityType: string | null;
  pendingProjectName: string | null;
  parentProposalId: string | null;
  intentGroupId: string | null;
  postedMessageTs: string | null;
  postedMessageChannel: string | null;
  resolvedProjectId: string | null;
  status: "pending" | "submitted" | "cancelled" | "expired" | "failed";
  expiresAt: Date | string;
  channelId: string;
  threadTs: string | null;
  userSlackId: string;
}

async function loadProposal(proposalId: string): Promise<ProposalRow | null> {
  const rows = await getRunwayDb()
    .select()
    .from(botModalProposals)
    .where(eq(botModalProposals.id, proposalId))
    .limit(1);
  const row = (rows[0] as ProposalRow | undefined) ?? null;
  return row;
}

type EntityKind = "task" | "project" | "team-member";

function toolKind(toolName: string): EntityKind {
  if (toolName === "create_project" || toolName === "update_project") return "project";
  if (toolName === "create_team_member" || toolName === "update_team_member") {
    return "team-member";
  }
  return "task";
}

interface BuildOpenInput {
  kind: EntityKind;
  mode: "create" | "edit";
  proposalId: string;
  args: Record<string, unknown>;
  retainerMode: boolean;
  baselineHint?: string;
  multiMatchHint?: string;
  currentValues?: Record<string, unknown>;
}

function buildViewForOpen(
  input: BuildOpenInput,
): Record<string, unknown> | null {
  if (input.kind === "task") {
    return buildTaskModal({
      args: input.args,
      proposalId: input.proposalId,
      mode: input.mode,
      currentValues: input.currentValues,
      baselineHint: input.baselineHint,
      multiMatchHint: input.multiMatchHint,
    }) as unknown as Record<string, unknown>;
  }
  if (input.kind === "project") {
    return buildProjectModal({
      args: input.args,
      proposalId: input.proposalId,
      mode: input.mode,
      retainerMode: input.retainerMode,
      currentValues: input.currentValues,
      baselineHint: input.baselineHint,
      multiMatchHint: input.multiMatchHint,
    }) as unknown as Record<string, unknown>;
  }
  return buildTeamMemberModal({
    args: input.args,
    proposalId: input.proposalId,
    mode: input.mode,
    currentValues: input.currentValues,
  }) as unknown as Record<string, unknown>;
}

function parsePrivateMetadata(raw: string | undefined): { proposalId?: string } {
  if (!raw) return {};
  try {
    const parsed = JSON.parse(raw) as Record<string, unknown>;
    return {
      proposalId: typeof parsed.proposalId === "string" ? parsed.proposalId : undefined,
    };
  } catch {
    return {};
  }
}

function isStateValuesShape(
  v: unknown,
): v is Record<string, Record<string, unknown>> {
  return typeof v === "object" && v !== null && !Array.isArray(v);
}

async function tryPostEphemeral(
  channel: string | undefined,
  user: string | undefined,
  text: string,
): Promise<void> {
  if (!channel || !user) return;
  try {
    await getSlackClient().chat.postEphemeral({ channel, user, text });
  } catch (err) {
    console.error("[slack-interactivity] postEphemeral failed", err);
  }
}

