    mockValidate.mockResolvedValue({
      ok: true,
      normalized: {
        clientId: "client-cgx",
        title: "Brief",
        owner: "Lane",
        date: "2026-05-10",
      },
      changedFields: ["owner", "date"],
    });
    mockUpdateWeekItemField.mockResolvedValue({
