      toolName,
      fuzzyTitle,
      currentUserSlackId: proposal.userSlackId,
      currentChannelId: proposal.channelId,
    });
    if (concurrent.hasConcurrent) {
      const warn = CONCURRENT_PROPOSAL_SOFT_WARN(
        concurrent.otherUser,
        concurrent.otherTitle,
